  switch (u.status) {
    case 'done':
      return u.url;
    case 'failed':
      return u.error;
    case 'pending':
      return `${u.progress ?? 0}%`;
    default: {
      const _exhaustive: never = u;
      return _exhaustive;
    }
  }
