## 2. Implementation (`parseDuration.ts`)

```ts
const DURATION_RE = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

/**
 * Parse a duration like '1h30m', '45s' or '2h' into seconds.
 * Units: h, m, s (in that order, each at most once). Throws on invalid input.
 */
export function parseDuration(s: string): number {
  if (typeof s !== 'string') {
    throw new TypeError(`parseDuration expects a string, got ${typeof s}`);
  }

  // The regex lets every group be optional, so the empty string matches.
  // Reject it here, along with anything that doesn't fit the pattern.
  const match = s === '' ? null : DURATION_RE.exec(s);
  if (!match) {
    throw new Error(`Invalid duration: ${JSON.stringify(s)}`);
  }

  const [, h, m, s_] = match;
  const total =
    Number(h ?? 0) * 3600 +
    Number(m ?? 0) * 60 +
    Number(s_ ?? 0);

  if (!Number.isSafeInteger(total)) {
    throw new Error(`Invalid duration (out of range): ${JSON.stringify(s)}`);
  }
  return total;
}
```

## Why it works

- **Ordering and duplicates:** the regex has three optional groups in a fixed order. `30m1h` and `1h1h` can't match, so no extra checks are needed.
- **Strictness:** the `^…$` anchors and `\d+` reject whitespace, signs, decimals and trailing junk like `1h30` (a number with no unit).
- **Empty string:** it matches the regex with all groups empty, so it is checked for explicitly.
- **Overflow:** `99999999999999999999s` becomes a float that isn't a safe integer, so it is rejected instead of returning a wrong number.

