```ts
const DURATION_RE = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

const SECONDS_PER_HOUR = 3600;
const SECONDS_PER_MINUTE = 60;

/**
 * Parses a duration like "1h30m", "45s" or "2h" into seconds.
 *
 * Format: optional hours, then optional minutes, then optional seconds
 * (in that order, each at most once), each a non-negative integer
 * followed by its unit. At least one component is required.
 *
 * @throws {TypeError}  if `s` is not a string
 * @throws {RangeError} if `s` is not a valid duration
 */
export function parseDuration(s: string): number {
  if (typeof s !== "string") {
    throw new TypeError(`Expected a string, got ${s === null ? "null" : typeof s}`);
  }

  const match = DURATION_RE.exec(s);
  // The regex matches "" (all groups optional), so reject it explicitly.
  if (s === "" || match === null) {
    throw new RangeError(`Invalid duration: ${JSON.stringify(s)}`);
  }

  const [, h, m, sec] = match;
  const total =
    Number(h ?? 0) * SECONDS_PER_HOUR +
    Number(m ?? 0) * SECONDS_PER_MINUTE +
    Number(sec ?? 0);

  if (!Number.isSafeInteger(total)) {
    throw new RangeError(`Duration out of range: ${JSON.stringify(s)}`);
  }

  return total;
}
```

## Why it works

- **Strictness comes from the regex.** The anchors, the fixed `h`, `m`, `s` order and the optional groups reject wrong order, duplicates, junk, whitespace, signs and decimals without extra checks.
- **Empty string is handled separately.** With every group optional, `""` would match and return 0, so it gets an explicit check.
- **Overflow is caught.** A huge value like `99999999999999999999h` turns into an imprecise float, and `Number.isSafeInteger` rejects it. Without that check it would silently return a wrong number.
- **`\d` in JavaScript is ASCII-only** (`[0-9]`), so Unicode digits such as `٣` are rejected.

